import pdfplumber
import pandas as pd

print("--- Inspecting population.pdf ---")
try:
    with pdfplumber.open("population.pdf") as pdf:
        if len(pdf.pages) > 0:
            page = pdf.pages[0]
            tables = page.extract_tables()
            if tables:
                print("First table found on page 1:")
                for row in tables[0][:3]: # Print first 3 rows
                    print(row)
            else:
                print("No tables found on page 1.")
        else:
            print("PDF is empty.")
except Exception as e:
    print(f"Error reading PDF: {e}")

print("\n--- Inspecting income.xlsx ---")
try:
    df = pd.read_excel("income.xlsx")
    print("Columns:", df.columns.tolist())
    print("First 3 rows:")
    print(df.head(3))
except Exception as e:
    print(f"Error reading Excel: {e}")

